div_intro:["{reg} will be at {loc}, where its last flight ended (diversion or change of destination). Your booking {dep} → {arr} on {t} needs it at {dep}.", "A {reg} estará em {loc}, onde terminou o último voo (desvio ou mudança de destino). Sua reserva {dep} → {arr} de {t} precisa dela em {dep}.", "{reg} estará en {loc}, donde terminó su último vuelo (desvío o cambio de destino). Tu reserva {dep} → {arr} del {t} la necesita en {dep}.", "{reg} sera à {loc}, fin de son dernier vol (déroutement ou changement de destination). Votre réservation {dep} → {arr} du {t} en a besoin à {dep}.", "{reg} ist in {loc}, wo der letzte Flug endete (Umleitung oder Zieländerung). Ihre Buchung {dep} → {arr} am {t} braucht es in {dep}."],
div_opt_ferry:["Bring it back with a ferry flight", "Trazer de volta com um voo de traslado", "Traerla con un vuelo de traslado", "La ramener par un convoyage", "Mit Überführungsflug zurückholen"],
div_ferry_txt:["You can fly {loc} → {dep} empty from {t} (about {d}), and then your flight stays as booked.", "Você pode voar {loc} → {dep} sem passageiros a partir de {t} (cerca de {d}), e depois seu voo continua como reservado.", "Puedes volar {loc} → {dep} vacío desde {t} (unos {d}) y tu vuelo sigue igual.", "Vous pouvez voler {loc} → {dep} à vide dès {t} (environ {d}), puis votre vol reste inchangé.", "Sie können {loc} → {dep} leer ab {t} fliegen (ca. {d}), danach bleibt Ihr Flug bestehen."],
div_ferry_btn:["Book ferry {loc} → {dep}", "Reservar traslado {loc} → {dep}", "Reservar traslado {loc} → {dep}", "Réserver le convoyage {loc} → {dep}", "Überführung {loc} → {dep} buchen"],
div_ferry_no:["There isn't enough time for a ferry {loc} → {dep} before your flight. Switch aircraft or wait for another pilot to bring it back.", "Não há tempo para um traslado {loc} → {dep} antes do seu voo. Troque de aeronave ou aguarde outro piloto trazê-la.", "No hay tiempo para un traslado {loc} → {dep} antes de tu vuelo. Cambia de aeronave o espera.", "Pas assez de temps pour un convoyage {loc} → {dep}. Changez d’avion ou attendez.", "Keine Zeit für eine Überführung {loc} → {dep}. Flugzeug wechseln oder warten."],
