let LI=LANGS.indexOf(lang);
function t(k,p){const r=L[k];let s=r?(r[LI]||r[0]):k;if(p)for(const x in p)s=s.split("{"+x+"}").join(p[x]);return s}
const tr=a=>a?(a[LI]||a[0]):"";
const ataName=n=>tr(ATA[n])||"";
const outLabel=o=>t("out_"+o);
const melLabel=d=>L["mel"+d]?t("mel"+d):d+" d";
const simName=s=>SIMS[s]||t("sim_other");
const phaseName=p=>{const i=PHASES.findIndex(x=>x[0]===p);return i<0?p:tr(PHASES[i])};
const defTitle=d=>d.catalogId&&CAT_BY_ID[d.catalogId]?tr(CAT_BY_ID[d.catalogId].t):d.title;
const defProc=d=>{const c=d.catalogId&&CAT_BY_ID[d.catalogId];return c&&c.p&&d.opsProcedure===c.p[0]?tr(c.p):d.opsProcedure};
let dtf,df,tf,dayf;
